```javascript
import * as THREE from 'three/webgpu';
import { color, uv, mix, mod, step, max, length, vec2 } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const disposables = [];
  const timelines = [];

  // Panel dimensions and colors
  const PANEL_W = 3.2;
  const PANEL_H = 2.2;
  const COLORS = {
    paper: new THREE.Color('#e8ecf2'),
    surface: new THREE.Color('#16161d'),
    gradLight: new THREE.Color('#14141a'),
    gradDark: new THREE.Color('#0b0b10'),
    accentLight: new THREE.Color('#ff4450'),
    accentDark: new THREE.Color('#c1121f'),
    accent: new THREE.Color('#ff2a38')
  };

  // Main panel with radial gradient + grid pattern
  const panelGeom = new THREE.PlaneGeometry(PANEL_W, PANEL_H);

  const panelUv = uv();
  const centerDist = length(vec2(panelUv.x.sub(0.5), panelUv.y.sub(0.5))).mul(1.414);
  const radialGrad = mix(
    color(COLORS.gradLight),
    color(COLORS.gradDark),
    centerDist.saturate()
  );

  // Grid pattern at 0.25-unit pitch (4 per panel)
  const gridUv = mod(panelUv.mul(4), 1);
  const gridLineX = step(0.96, gridUv.x);
  const gridLineY = step(0.96, gridUv.y);
  const gridAlpha = max(gridLineX, gridLineY).mul(0.06);

  const panelColor = mix(radialGrad, color(COLORS.paper), gridAlpha);
  const panelMat = new THREE.MeshBasicNodeMaterial({ colorNode: panelColor });
  const panel = new THREE.Mesh(panelGeom, panelMat);
  group.add(panel);
  disposables.push(panelGeom, panelMat);

  // Ghost preview (left of center)
  const ghostGroup = new THREE.Group();
  ghostGroup.position.x = -0.6;
  ghostGroup.position.z = 0.01;

  // Wireframe geometry
  const wireGeom = new THREE.BufferGeometry();
  const vertices = [];

  // Watch card outline (1.1w x 1.4h)
  const cw = 0.55;
  const ch = 0.7;
  vertices.push(
    -cw, -ch, 0, cw, -ch, 0,
    cw, -ch, 0, cw, ch, 0,
    cw, ch, 0, -cw, ch, 0,
    -cw, ch, 0, -cw, -ch, 0
  );

  // Dial circle (0.55 diameter)
  const dialRadius = 0.275;
  const dialSegments = 32;
  for (let i = 0; i < dialSegments; i++) {
    const angle1 = (i / dialSegments) * Math.PI * 2;
    const angle2 = ((i + 1) / dialSegments) * Math.PI * 2;
    vertices.push(
      Math.cos(angle1) * dialRadius, Math.sin(angle1) * dialRadius, 0,
      Math.cos(angle2) * dialRadius, Math.sin(angle2) * dialRadius, 0
    );
  }

  // Two text bars (0.7w x 0.06h)
  const barW = 0.35;
  const barH = 0.03;
  const bar1Y = 0.3;
  const bar2Y = 0.45;

  for (const barY of [bar1Y, bar2Y]) {
    vertices.push(
      -barW, barY - barH, 0, barW, barY - barH, 0,
      barW, barY - barH, 0, barW, barY + barH, 0,
      barW, barY + barH, 0, -barW, barY + barH, 0,
      -barW, barY + barH, 0, -barW, barY - barH, 0
    );
  }

  wireGeom.setAttribute('position', new THREE.BufferAttribute(new Float32Array(vertices), 3));

  const wireMat = new THREE.LineBasicMaterial({
    color: COLORS.paper,
    transparent: true,
    opacity: 0.3,
    linewidth: 1
  });

  const wireframe = new THREE.LineSegments(wireGeom, wireMat);
  ghostGroup.add(wireframe);

  // Ghost breathing animation (0.24 -> 0.34 over 2400ms)
  const ghostTL = gsap.timeline({ repeat: -1 });
  ghostTL
    .to(wireMat, {
      opacity: 0.34,
      duration: 2.4,
      ease: 'cubic-bezier(0.445, 0.05, 0.55, 0.95)'
    }, 0)
    .to(wireMat, {
      opacity: 0.24,
      duration: 2.4,
      ease: 'cubic-bezier(0.445, 0.05, 0.55, 0.95)'
    }, 2.4);

  timelines.push(ghostTL);
  group.add(ghostGroup);
  disposables.push(wireGeom, wireMat);

  // Copy column (headline + body, right of ghost)
  const copyGroup = new THREE.Group();
  copyGroup.position.x = 0.8;
  copyGroup.position.z = 0.01;

  // Headline
  const headlineLayout = ctx.fontAtlas.layout('Your ledger is empty.', {
    family: 'Lora',
    size: 34,
    weight: 600,
    letterSpacing: -0.01
  });
  const headlineMesh = ctx.fontAtlas.render(headlineLayout, { color: COLORS.paper });
  headlineMesh.position.y = 0.3;
  copyGroup.add(headlineMesh);

  // Body
  const bodyLayout = ctx.fontAtlas.layout(
    'Commissioned pieces and saved references will appear here once you begin.',
    {
      family: 'JetBrains Mono',
      size: 13,
      weight: 400,
      lineHeight: 1.5,
      maxWidth: 1.2
    }
  );
  const bodyMesh = ctx.fontAtlas.render(bodyLayout, { color: COLORS.paper });
  bodyMesh.position.y = -0.15;
  copyGroup.add(bodyMesh);

  group.add(copyGroup);

  // CTA Button (1.5w x 0.36h, below body)
  const btnGroup = new THREE.Group();
  btnGroup.position.y = -0.8;
  btnGroup.position.z = 0.02;

  // Button background with vertical gradient
  const btnGeom = new THREE.PlaneGeometry(1.5, 0.36);

  const btnUv = uv();
  const btnGradient = mix(
    color(COLORS.accentLight),
    color(COLORS.accentDark),
    btnUv.y.add(0.5).saturate()
  );

  const btnMat = new THREE.MeshBasicNodeMaterial({ colorNode: btnGradient });
  const btnBg = new THREE.Mesh(btnGeom, btnMat);
  btnGroup.add(btnBg);
  disposables.push(btnGeom, btnMat);

  // Button text
  const ctaLayout = ctx.fontAtlas.layout('BROWSE THE COLLECTION', {
    family: 'JetBrains Mono',
    size: 13,
    weight: 700,
    letterSpacing: 0.08
  });
  const ctaMesh = ctx.fontAtlas.render(ctaLayout, { color: COLORS.surface });
  ctaMesh.position.z = 0.01;
  btnGroup.add(ctaMesh);

  // Button press interaction
  btnGroup.userData.handlers = {
    click: () => {
      gsap.to(btnGroup.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'cubic-bezier(0.175, 0.885, 0.32, 1.275)',
        yoyo: true,
        repeat: 1
      });
    }
  };

  group.add(btnGroup);

  // Mount animation (fade-up: opacity 0->1, y +0.2->0 over 500ms)
  const mountTL = gsap.timeline();
  mountTL.from(group, {
    opacity: 0,
    y: 0.2,
    duration: 0.5,
    ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
  });
  timelines.push(mountTL);

  // Apply scene placement
  if (config.scenePosition) {
    group.position.copy(config.scenePosition);
  }
  if (config.sceneRotation) {
    group.rotation.order = 'XYZ';
    if (config.sceneRotation.x !== undefined) group.rotation.x = config.sceneRotation.x;
    if (config.sceneRotation.y !== undefined) group.rotation.y = config.sceneRotation.y;
    if (config.sceneRotation.z !== undefined) group.rotation.z = config.sceneRotation.z;
  }
  if (config.sceneScale) {
    group.scale.copy(config.sceneScale);
  }

  // Cleanup function
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    gsap.killTweensOf([group, btnGroup, wireMat]);
    disposables.forEach(obj => obj.dispose?.());
  };

  return group;
}
